/**
 * Auth Service — Core authentication business logic.
 * Handles registration, login, admin 2FA, tokens, and password reset.
 * Generated by BackendForge
 */

const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const crypto = require('crypto');
const { env } = require('../config/env');
const { ApiError } = require('../middleware/error-handler.middleware');
const { generateOTP, verifyOTP } = require('../utils/otp-generator');
const { sendEmail } = require('../config/email');
const { sendSMS } = require('../config/sms');
const { User, OTP } = require('../models');

const authService = {
  /**
   * Register a new customer.
   */
  async register({ name, email, phone, password }) {
    // Check if user exists
    const existing = await User.scope('withPassword').findOne({ where: { email: email.toLowerCase() } });
    if (existing) {
      throw ApiError.conflict('An account with this email already exists', 'EMAIL_EXISTS');
    }

    // Create user
    const user = await User.create({
      name,
      email: email.toLowerCase(),
      phone: phone || null,
      passwordHash: password, // Will be hashed by beforeCreate hook
      role: 'customer',
    });

    const tokens = this.generateTokens(user);

    // Save refresh token
    await User.update({ refreshToken: tokens.refreshToken }, { where: { id: user.id } });

    return {
      user: this.sanitizeUser(user),
      ...tokens,
    };
  },

  /**
   * Customer login.
   */
  async login(email, password) {
    const user = await User.scope('withPassword').findOne({ where: { email: email.toLowerCase() } });

    if (!user) {
      throw ApiError.unauthorized('Invalid email or password', 'INVALID_CREDENTIALS');
    }

    if (!user.isActive) {
      throw ApiError.forbidden('Account has been deactivated', 'ACCOUNT_DEACTIVATED');
    }

    const isMatch = await bcrypt.compare(password, user.passwordHash);

    if (!isMatch) {
      throw ApiError.unauthorized('Invalid email or password', 'INVALID_CREDENTIALS');
    }

    // Update last login
    await User.update({ lastLoginAt: new Date() }, { where: { id: user.id } });

    const tokens = this.generateTokens(user);
    await User.update({ refreshToken: tokens.refreshToken }, { where: { id: user.id } });

    return {
      user: this.sanitizeUser(user),
      ...tokens,
    };
  },

  /**
   * Admin login step 1 — Verify credentials, then send OTP to email + phone.
   */
  async adminLoginStep1(email, password) {
    const user = await User.scope('withPassword').findOne({
      where: { email: email.toLowerCase(), role: ['admin', 'superadmin'] },
    });

    if (!user) {
      throw ApiError.unauthorized('Invalid admin credentials', 'INVALID_CREDENTIALS');
    }

    const isMatch = await bcrypt.compare(password, user.passwordHash);

    if (!isMatch) {
      throw ApiError.unauthorized('Invalid admin credentials', 'INVALID_CREDENTIALS');
    }

    // Generate and save OTP
    const otpCode = generateOTP();
    const expiresAt = new Date(Date.now() + (parseInt(env.OTP_EXPIRY_MINUTES) || 5) * 60 * 1000);

    // Delete any existing OTPs for this user
    await OTP.destroy({ where: { userId: user.id, purpose: 'admin_login' } });
    await OTP.create({
      userId: user.id,
      code: otpCode,
      channel: 'both',
      purpose: 'admin_login',
      expiresAt,
    });

    // Send OTP via email
    const otpSentTo = [];
    const emailResult = await sendEmail({
      to: user.email,
      subject: 'Admin Login OTP — demo-store-backend',
      html: `<h2>Admin Login Verification</h2><p>Your OTP code is: <strong>${otpCode}</strong></p><p>This code expires in ${env.OTP_EXPIRY_MINUTES || 5} minutes.</p><p>If you didn't request this, please secure your account immediately.</p>`,
      text: `Your admin login OTP is: ${otpCode}. Expires in ${env.OTP_EXPIRY_MINUTES || 5} minutes.`,
    });
    if (emailResult.success) otpSentTo.push('email');

    // Send OTP via SMS (if phone number exists)
    if (user.phone) {
      const smsResult = await sendSMS(user.phone, `Your admin login OTP for demo-store-backend is: ${otpCode}. Expires in ${env.OTP_EXPIRY_MINUTES || 5} min.`);
      if (smsResult.success) otpSentTo.push('phone');
    }

    return {
      userId: user.id,
      otpSentTo,
    };
  },

  /**
   * Admin login step 2 — Verify OTP, issue tokens.
   */
  async adminLoginStep2(userId, code) {
    const otpResult = await verifyOTP(userId, code, 'admin_login');
    if (!otpResult.valid) {
      throw ApiError.unauthorized(otpResult.message || 'Invalid or expired OTP', 'INVALID_OTP');
    }

    const user = await User.findByPk(userId);

    if (!user) throw ApiError.notFound('User not found');

    await User.update({ lastLoginAt: new Date() }, { where: { id: user.id } });

    const tokens = this.generateTokens(user);
    await User.update({ refreshToken: tokens.refreshToken }, { where: { id: user.id } });

    return {
      user: this.sanitizeUser(user),
      ...tokens,
    };
  },

  /**
   * Refresh access token using refresh token.
   */
  async refreshAccessToken(refreshToken) {
    try {
      const decoded = jwt.verify(refreshToken, env.JWT_SECRET);

      const user = await User.scope('withRefreshToken').findByPk(decoded.userId);
      if (!user || user.get('refreshToken') !== refreshToken) {
        throw ApiError.unauthorized('Invalid refresh token', 'INVALID_REFRESH_TOKEN');
      }

      const tokens = this.generateTokens(user);
      await User.update({ refreshToken: tokens.refreshToken }, { where: { id: user.id } });

      return tokens;
    } catch (error) {
      if (error.name === 'TokenExpiredError') {
        throw ApiError.unauthorized('Refresh token expired. Please login again.', 'REFRESH_TOKEN_EXPIRED');
      }
      throw error;
    }
  },

  /**
   * Generate JWT access + refresh tokens.
   */
  generateTokens(user) {
    const userId = user.id;
    const accessToken = jwt.sign(
      { userId, email: user.email, role: user.role },
      env.JWT_SECRET,
      { expiresIn: env.JWT_EXPIRY || '24h' }
    );
    const refreshToken = jwt.sign(
      { userId, type: 'refresh' },
      env.JWT_SECRET,
      { expiresIn: env.JWT_REFRESH_EXPIRY || '7d' }
    );
    return { accessToken, refreshToken };
  },

  /**
   * Forgot password — Send reset link.
   */
  async forgotPassword(email) {
    const user = await User.findOne({ where: { email: email.toLowerCase() } });
    if (!user) return; // Don't reveal if email exists

    const resetToken = crypto.randomBytes(32).toString('hex');
    const hashedToken = crypto.createHash('sha256').update(resetToken).digest('hex');

    await User.update(
      { passwordResetToken: hashedToken, passwordResetExpires: new Date(Date.now() + 30 * 60 * 1000) },
      { where: { id: user.id } }
    );

    const resetUrl = `${env.FRONTEND_URL}/reset-password?token=${resetToken}`;
    await sendEmail({
      to: user.email,
      subject: 'Password Reset — demo-store-backend',
      html: `<h2>Password Reset</h2><p>Click the link below to reset your password:</p><a href="${resetUrl}">${resetUrl}</a><p>This link expires in 30 minutes.</p>`,
    });
  },

  /**
   * Reset password with token.
   */
  async resetPassword(token, newPassword) {
    const hashedToken = crypto.createHash('sha256').update(token).digest('hex');

    const { Op } = require('sequelize');
    const user = await User.scope('withPassword').findOne({
      where: {
        passwordResetToken: hashedToken,
        passwordResetExpires: { [Op.gt]: new Date() },
      },
    });

    if (!user) {
      throw ApiError.badRequest('Invalid or expired reset token', 'INVALID_RESET_TOKEN');
    }

    const hashed = await bcrypt.hash(newPassword, parseInt(env.BCRYPT_ROUNDS) || 12);
    await User.update(
      { passwordHash: hashed, passwordResetToken: null, passwordResetExpires: null, refreshToken: null },
      { where: { id: user.id } }
    );
  },

  /**
   * Logout — Blacklist token and clear refresh token.
   */
  async logout(userId, token) {
    // Blacklist the access token in Redis
    try {
      const { getRedisClient } = require('../config/redis');
      const redis = getRedisClient();
      if (redis && token) {
        const decoded = jwt.decode(token);
        const ttl = decoded?.exp ? decoded.exp - Math.floor(Date.now() / 1000) : 86400;
        if (ttl > 0) {
          await redis.set(`bl_${token}`, '1', { EX: ttl });
        }
      }
    } catch (err) {
      console.error('Token blacklist failed:', err.message);
    }

    // Clear refresh token
    await User.update({ refreshToken: null }, { where: { id: userId } });
  },

  /**
   * Strip sensitive fields from user object.
   */
  sanitizeUser(user) {
    const obj = user.toSafeJSON ? user.toSafeJSON() : user.get({ plain: true });
    delete obj.passwordHash;
    delete obj.refreshToken;
    delete obj.passwordResetToken;
    delete obj.passwordResetExpires;
    return obj;
  },
};

module.exports = authService;
